def solve(n, A):
    p = 10 ** 9 + 7
    nums = {n - 2 * i - 1: 0 for i in range(ceil(n / 2))}
    for a in A:
        if (a not in nums) or (a == 0 and nums[a] == 1) or (nums[a] == 2):
            return 0
        nums[a] += 1
    ret = 1
    for _ in range(n // 2):
        ret = (ret * 2) % p
    return ret

