# find:     O(alpha(N))
# union:    O(alpha(N)) or O(alpha(N)logN) グループの要素も管理する場合
class UnionFind:
    def __init__(self, n):
        self.n = n              # 頂点数
        self.parent = [-1] * n  # >0のとき根のインデックス、<0のときは根で-(グループの要素数)
        self.grpcnt = n         # 全体のグループ数
        self.members = [{i} for i in range(n)]  # 各グループに含まれる要素の集合

    # 根を求める
    def find(self, x):
        if self.parent[x] < 0:
            return x
        else:
            self.parent[x] = self.find(self.parent[x])  # 経路圧縮
            return self.parent[x]

    # まとめる
    # グループの要素も管理すると、O(alpha(N)) からO(alpha(N)logN)となる
    def union(self, x, y):
        x = self.find(x)
        y = self.find(y)

        if x == y: return False

        self.grpcnt -= 1    # まとめるのでグループ数が1減る

        # グループのサイズが大きい方にまとめる
        if self.parent[x] > self.parent[y]:     # xのほうが要素数が少ない場合はスワップしておく
            x, y = y, x

        # x <- y
        self.parent[x] += self.parent[y]    # 要素数を加算
        self.parent[y] = x                  # 根を更新
        self.members[x].update(self.members[y])     # 要素の集合を更新
        return True

    def is_same(self, x, y):
        return self.find(x) == self.find(y)

    # 根の要素のリストを返す
    def roots(self):
        return [i for i, x in enumerate(self.parent) if x < 0]

    # xが含まれるグループに含まれる要素数を返す
    def get_size(self, x):
        return -self.parent[self.find(x)]

    # すべてのグループの要素数を返す
    def get_all_size(self):
        res = []
        for i, v in enumerate(self.parent):
            if v < 0: res.append(-v)
        return res

    # xが含まれるグループの要素を返す
    def get_members(self, x):
        return self.members[self.find(x)]

    # すべてのグループの要素を返す
    def get_all_members(self):
        res = []
        for i, v in enumerate(self.parent):
            if v < 0: res.append(self.members[i])
        return res

class UnionFind2:
    def __init__(self, n):
        self.parent = [-1] * n
        self.size_table = [1] * n
        self.grpcnt = n

    def find(self, x):
        stack = []
        while self.parent[x] >= 0:
            stack.append(x)
            x = self.parent[x]
        for v in stack:
            self.parent[v] = x
        return x

    def union(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if x == y: return False

        self.grpcnt -= 1
        if -self.parent[x] < -self.parent[y]:
            x, y = y, x

        self.parent[x] += self.parent[y]
        self.parent[y] = x
        return True

    def is_same(self, x, y):
        return self.find(x) == self.find(y)

    # {root: [members, ... ,]}
    def get_all_members(self):
        res = defaultdict(list)
        for i, v in enumerate(self.parent):
            if v < 0:
                res[i].append(i)
            else:
                res[self.find(v)].append(i)
        return res

