def make_divisors(x):
    l_div, u_div = [], []
    i = 1
    while i * i <= x:
        if x % i == 0:
            l_div.append(i)
            if i != x // i:
                u_div.append((x // 1))
        i += 1
    return l_div + u_div[::-1]


def dup_list_d(l):
    l1 = l.copy()
    ret = [None] * (len(l) + len(l1))
    ret[::2] = l
    ret[1::2] = l1
