class Joisino():
    def __init__(self, input_data: str):
        self.first_number = int(input_data.split()[0])
        self.second_number = int(input_data.split()[2])
        self.operator = input_data.split()[1]

    @staticmethod
    def calc_plus(value1, value2):
        return value1 + value2

    @staticmethod
    def calc_minus(value1, value2):
        return value1 - value2

    def execute_operation(self):
        if self.operator == '+':
            return self.calc_plus(self.first_number, self.second_number)
        elif self.operator == '-':
            return self.calc_minus(self.first_number, self.second_number)


