def factorial(n):
    # 試し割りによる素因数分解
    prime_count = Counter()

    for i in range(2, int(math.sqrt(n)) + 2):
        while n % i == 0:
            n /= i
            prime_count[i] += 1
    if n > 1:
        prime_count[int(n)] += 1

    return prime_count


def solve(N: int):

    primes = Counter()
    for i in range(1, N+1):
        primes += factorial(i)

    tot = 1
    for key in primes:
        tot *= primes[key]+1
        tot %= MOD

    print(tot)
    return


