    N, M = map(int, input().split())
    AB = [list(map(int, input().split())) for _ in range(M)]
    path = {}
    for a, b in AB:
        a-= 1
        b-=1
        if a in path:
            path[a].append(b)
        else:
            path[a] = [b]
        if b in path:
            path[b].append(a)
        else:
            path[b] = [a]

    S = [[0]*N for _ in range(2**N)]    #S[S][v] 頂点Sを訪問済みでvにいるときの個数
    S[1][0] = 1
    for i in range(1, 2**N):
        for j in range(N):
            if i >> j & 1:
                for k in path[j]:
                    if not (i>>k & 1):
                        S[1<<k|i][k] += S[i][j]
    ans = 0
    for i in range(1,N):
        ans += S[2**N-1][i]
    print(ans)


