        self.N=N
        self.sima=[[] for _ in range(N)]
        self.check=[[0] for _ in range(N)] 
        self.ans=0

    def add(self,a,b):
        self.sima[a].append(b)
        self.sima[b].append(a)

    def test(self):
        return self.sima

    def serch(self,start):
        from collections import deque
        que=deque([[start]])
        while que:
            n=que.pop()
            self.check[n]=1
            for t in self.sima[n]:
                if self.check[t]==0:
                    que.append([t])

    def reserch(self,now,checker=[],l=0):
        import copy
        if l==0:
            checker=[0 for _ in range(self.N)]
        l+=1
        checker[now]=1
        if l==self.N:
            self.ans+=1

        for i in self.sima[now]:
            if checker[i]==0:
                self.reserch(i,copy.deepcopy(checker),l)
        # print(now,self.sima[now],checker,l,self.N,self.ans)

    def print_ans(self):
        print(self.ans)





