import sys

from collections import deque
from collections import defaultdict

class Graph:
    def __init__(self):
        self.edges = defaultdict(dict)

    def append_edge(self, sv, ev, weight = 1):
        self.edges[sv][ev] = 1

    def remove_edge(self, sv, ev, weight = 1):
        if sv in self.edges:
            if ev in self.edges[sv]:
                del self.edges[sv][ev]

    def bfs(self, sv, N):
        dist = [-1]*N
        q = deque([])   # キュー
        q.append(sv)
        dist[sv] = 0
        connect_vtxs = []
        root = [-1]*N
        while len(q) > 0:
            p = q.popleft()     # キュー取りだし（先頭）
