def SSP(a, li=None):
    if li is None:
        li = []
    if len(a) == 1:
        return [a[0]]
    return list(set(li + SSP(a[1:], li) + list(map(lambda x: x + a[0], SSP(a[1:], li))) + [a[0]]))


def LIS(b):
    l = [b[0]]
    for i in b:
        if i > l[-1]:
            l += [i]
        else:
            l[bisect.bisect_left(l, i)] = i
    return len(l)


def is_prime(n):
    if n == 1: return False
    if n == 2: return True

    for k in range(100):
        a = random.randint(2, n - 1)

        if math.gcd(n, a) != 1:
            return False

        if pow(a, n - 1, n) != 1:
            return False

    return True


def BFS(g, s):
    dist = [float("INF")] * len(g)
    dist[s] = 0
    q, pos = collections.deque([s]), [False] * len(g)
    while q:
        s = q.popleft()
        for i in g[s]:
            if not pos[i]:
                dist[i] = dist[s] + 1
                pos[i] = True
                q.append(i)
    return dist


def warshall_floyd(g):
    n = len(g)
    d = [[float("INF")] * n for i in range(n)]
    for i in range(n):
        for j, k in g[i]:
            d[i][j] = k
    for i in range(n):
        for j in range(n):
            for k in range(n):
                d[i][j] = min(d[i][j], d[i][k] + d[k][j])
    return d


def dijkstra(g, s):
    n = len(g)
    dist = [float("INF")] * n
    dist[s] = 0
    hq = [(0, s)]
    seen = [False] * n
    while hq:
        v = heapq.heappop(hq)[1]
        seen[v] = True
        for to, cost in g[v]:
            if seen[to] == False and dist[v] + cost < dist[to]:
                dist[to] = dist[v] + cost
                heapq.heappush(hq, (dist[to], to))
    return dist


