vis = [False for i in range(n + 1)]
def dfs(v, adj, count, vis):
    if(v == n):
        return True
    if(count > 2):
        return False
    count += 1
    if(vis[v]):
        return False
    vis[v] = True
    for u in adj[v]:
        res = False
        if(vis[u] == False):
            res = dfs(u, adj, count + 1, vis)
        if(res):
            return True
    return False

