import sys
import math

#
# A*B=Nを満たすA,Bの組を全て列挙してF(A,B)の最小値を計算したい．
# A>Bを満たす組はA<Bを満たす組を入れ替えて得られるので，A<=Bを満たす組のみ列挙すればよい．
# A*A <= A*B <= N より A <= sqrt(N) が成り立つので，1 <= A <= sqrt(N)の範囲のみ調べればよく，O(sqrt(N))で計算できる．
#

def get_keta(n):
	return len(str(int(n)))

def solve(N):
	ans = 10
	for i in range(1, int(math.sqrt(N)) + 1):
		if N % i == 0:
			ans = min(ans, max(get_keta(i), get_keta(N / i)))
	print(ans)
	return

def main():
	def iterate_tokens():
		for line in sys.stdin:
			for word in line.split():
				yield word
	tokens = iterate_tokens()
	N = int(next(tokens))
	solve(N)

if __name__ == '__main__':
	main()

