from collections import deque
from typing import List


def solve(n: int, a: List[int]) -> List[int]:
    b = deque()
    for i in range(n):
        if i % 2 == 0:
            b.append(a[i])
        else:
            b.appendleft(a[i])

    if n % 2 != 0:
        b = reversed(b)

    return list(b)


def main():
    n = int(input())
    a = list(map(int, input().split()))
    print(*solve(n, a))


