class MetaSingleton(type):
    Nil = {}

    def __call__(cls, *args):
        if cls not in cls.Nil:
            cls.Nil[cls] = super().__call__(*args)
        return cls.Nil[cls] if not args else super().__call__(*args)


class ListStack(metaclass=MetaSingleton):
    def __init__(self, head=None, tail=None):
        self._head = head
        self._tail = tail

    def __bool__(self):
        return self is not self.__class__.Nil[self.__class__]

    def __iter__(self):
        ptr = self
        while ptr:
            yield ptr.head()
            ptr = ptr.tail()

    def cons(self, value):
        return self.__class__(value, self)

    def head(self):
        if self is self.__class__.Nil[self.__class__]:
            raise IndexError("pop from empty list")
        return self._head

    def tail(self):
        if self is self.__class__.Nil[self.__class__]:
            raise IndexError("pop from empty list")
        return self._tail

    def reverse(self):
        ret = self.__class__.Nil[self.__class__]
        for x in self:
            ret = ret.cons(x)
        return ret

    def concat(self, other):
        ret = other
        for x in self.reverse():
            ret = ret.cons(x)
        return ret

    def take(self, n):
        ret = self.__class__.Nil[self.__class__] 
        for i, x in enumerate(self):
            if i == n:
                break
            ret = ret.cons(x)
        return ret.reverse()

    def drop(self, n):
        ret = self
        for _ in range(n):
            if not ret:
                break
            ret = ret.tail()
        return ret


class BatchedDeque:
    def __init__(self, fsize=0, f=None, rsize=0, r=None):
        self.fsize = fsize
        self.f = ListStack() if f is None else f
        self.rsize = rsize
        self.r = ListStack() if r is None else r

    def __bool__(self):
        return self.fsize + self.rsize != 0

    def _check(self):
        if self.fsize == 0:
            half = (self.fsize + self.rsize) // 2
            self.f = self.r.drop(half).reverse()
            self.r = self.r.take(half)
            self.fsize = self.rsize - half
            self.rsize = half
        elif self.rsize == 0:
            half = (self.fsize + self.rsize) // 2
            self.r = self.f.drop(half).reverse() 
            self.f = self.f.take(half)
            self.rsize = self.fsize - half
            self.fsize = half
        return self

    def cons(self, value):
        return BatchedDeque(self.fsize + 1, self.f.cons(value),
                            self.rsize, self.r)._check()

    def head(self):
        if not self:
            raise IndexError("head from empty deque")
        if self.fsize == 0:
            return self.r.head()
        return self.f.head()

    def tail(self):
        if not self: 
            raise IndexError("tail from empty deque")
        if self.fsize == 0:
            return BatchedDeque()
        return BatchedDeque(self.fsize - 1, self.f.tail(),
                            self.rsize, self.r)._check()

    def snoc(self, value):
        return BatchedDeque(self.fsize, self.f,
                            self.rsize + 1, self.r.cons(value))._check()

    def last(self):
        if not self:
            raise IndexError("last from empty deque")
        if self.rsize == 0:
            return self.f.head()
        return self.r.head()

    def init(self):
        if not self:
            raise IndexError("init from empty deque")
        if self.rsize == 0:
            return BatchedDeque()
        return BatchedDeque(self.fsize, self.f,
                            self.rsize - 1, self.r.tail())._check()


