def prepare():
    _ = int(input())
    A = list(map(int, input().split(" ")))
    return A


def check_color_num(A):
    rates = {
        "gray": (1, 399),
        "blown": (400, 799),
        "green": (800, 1199),
        "light_blue": (1200, 1599),
        "blue": (1600, 1999),
        "yellow": (2000, 2399),
        "orange": (2400, 2799),
        "red": (2800, 3199)
    }
    color_variation = set()
    master_num = 0
    min_color_num = None
    max_color_num = None
    for a in A:
        if 3200 <= a:
            master_num += 1
            continue
        for k, v in rates.items():
            min_, max_ = v
            if min_ <= a <= max_:
                color_variation.add(k)
                break
    if 1 <= master_num:
        if len(color_variation) == 0:
            min_color_num = 1
        else:
            min_color_num = len(color_variation)
        max_color_num = len(color_variation) + master_num
    else:
        min_color_num = max_color_num = len(color_variation)
    return min_color_num, max_color_num


