from typing import Dict

def solve(string: str) -> str:
    # if string's length is odd
    if len(string) & 1:
        return 'No'

    # count characters
    char_counts: Dict[str, int] = {}
    for char in string:
        if char in char_counts:
            char_counts[char] += 1
        else:
            char_counts[char] = 1

    # check if all count is even
    for char_count in char_counts.values():
        if char_count & 1:
            return 'No'

    return 'Yes'

