def combi(n, k, MOD=pow(10, 9)+7) -> int:
    numer = 1
    for i in range(n, n-k, -1):
        numer *= i
        numer %= MOD
    denom = 1
    for j in range(k, 0, -1):
        denom *= j
        denom %= MOD
    return (numer*(pow(denom, MOD-2, MOD)))%MOD

def perm(n, k, MOD=pow(10, 9)+7) -> int:
    numer = 1
    for i in range(n, n-k, -1):
        numer *= i
        numer %= MOD
    return numer

