class Graph:
    def __init__(self):
        self.edges = {}

    def append_edge(self, sv, ev, weight = 1):
        if sv in self.edges:
            self.edges[sv].append((ev, weight))
        else:
            self.edges[sv] = [(ev, weight)]

    def bellman_ford(self, sv, N):
        dist = [float('inf')] * N
        dist[sv] = 0
        for i in range(N):
            update = [False] * N
            for a, v in self.edges.items():
                for b, c in v:
                    if  dist[a] + c < dist[b]:
                        dist[b] = dist[a] + c
                        update[b] = True

                if i == N - 1 and update[N - 1]:
                    return -float('inf')

        return dist[N - 1]

