def bellmanFord(n, edges, cost, s, g) -> bool:
    """
    始点sから到達可能かつ終点gへ到達可能は負閉路が検出されたときFalse
    それ以外True

    costはINFに初期化されたリストを渡す
    """
    cost[s] = 0
    for i in range(2*n):
        for fr, to, c in edges:
            if cost[fr] < INF and cost[fr] + c < cost[to]:
                if i >= n-1 and to == g:
                    return False
                elif i >= n-1:
                    cost[to] = -INF
                else:
                    cost[to] = cost[fr] + c
    return True




