from math import inf
from typing import List
from dataclasses import dataclass


@dataclass
class Edge:
  to: int
  weight: float


N, M = list(map(int, input().split()))
graph: List[List[Edge]] = [[] for _ in range(N)]
for _ in range(M):
  a, b, w = list(map(int, input().split()))
  graph[a - 1].append(Edge(b - 1, -w))


def chmin(v, dp, idx):
  if v < dp[idx]:
    dp[idx] = v
    return True
  return False


def search(graph: List[List[Edge]], N: int, start: int):
  neg_cyc = False

  dist = [inf] * N
  dist[start] = 0

  for i in range(N):
    update = False
    for v in range(N):
      if dist[v] == inf:
        continue

      for e in graph[v]:
        if chmin(dist[v] + e.weight, dist, e.to):
          update = True
    if not update:
      break
  else:
    if update:
      neg_cyc = True
  return neg_cyc, -dist[-1]


def is_reachable(N):
  r_G = [[] for _ in range(N)]
  for x, edges in enumerate(graph):
    for edge in edges:
      r_G[edge.to].append(x)
  reach = [False] * N
  task = [N - 1]
  while task:
    idx = task.pop()
    reach[idx] = True
    for v in r_G[idx]:
      if not reach[v]:
        task.append(v)
  return reach


def main():
  reach = is_reachable(N)
  reachable_graph = [[g for g in f if reach[g.to]] if reach[i] else [] for i, f in enumerate(graph)]
  neg_cyc, last_dist = search(reachable_graph, N, 0)
  if neg_cyc:
    return "inf"
  else:
    return last_dist


if __name__ == "__main__":
  print(main())

