        if self.rank[root_x] < self.rank[root_y]:
            self.par[root_x] = root_y
        elif self.rank[root_y] < self.rank[root_x]:
            self.par[root_y] = root_x
        else:
            self.par[root_y] = root_x
            self.rank[root_x] += 1

  def same(self, x, y):
        return self.find(x) == self.find(y)
