def solve_abc045c(S):

    N = len(S)-1
    ans = 0
    for bit in range(1 << N):
        op = ["" for _ in range(N)]
        for i in range(N):
            if bit & (1 << i):
                op[i] = "+"
        s = "".join(S[i]+op[i] for i in range(N)) + S[-1]
        ans += sum(int(t) for t in s.split('+'))

    return ans


