def gen_2d_array(n, m, fill=0):
    if callable(fill):
        return [[fill() for _ in range(m)] for _ in range(n)]
    else:
        return [[fill] * m for _ in range(n)]


def gen_3d_array(n, m, k, fill=0):
    if callable(fill):
        return [[[fill() for _ in range(k)] for _ in range(m)] for _ in range(n)]
    else:
        return [[[fill] * k for _ in range(m)] for _ in range(n)]


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.perf_counter()
        ret = f(*args, **kwargs)
        e = time.perf_counter()

        ep(e - s, 'sec')
        return ret

    return wrap


