def make_divisors(n):
    divisors = []
    for i in range(1, int(n**0.5)+1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n//i)

    divisors.sort()
    return divisors


def reverse(S):
    X = []
    str = ""
    for i in range(len(S)):
        i += 1
        X.append(S[-i])

    return str.join(X)


def permutation(l):
    return list(it.permutations(l))


def combination(l, p):
    return list(it.combinations(l, p))


def getNearestNum(l, n):
    idx = np.abs(np.asarray(l) - n).argmin()
    return l[idx]


