def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True

    for i in range(2,n):
        if n%i == 0:
            return False
    return True

def spl(ar,n):
    return [ar[idx:idx + n] for idx in range(0,len(ar), n)]

def factorization(n):
    arr = []
    temp = n
    for i in range(2, int(-(-n**0.5//1))+1):
        if temp%i==0:
            cnt=0
            while temp%i==0:
                cnt+=1
                temp //= i
            arr.append([i, cnt])

    if temp!=1:
        arr.append([temp, 1])

    if arr==[]:
        arr.append([n, 1])

    return arr

def ncombination(n,r):
    k = 1
    v = 1
    for i in range(r):
        k *= n
        n -= 1
    for j in range(r):
        v *= r
        r -= 1

    return int(k/v)
