      self.bn += 1;
      if(self.bn == self.bm+1):
        return "B"
      else:
        return game.play(self, self.b[self.bn-1])
    else:
      self.cn += 1;
      if(self.cn == self.cm+1):
        return "C"
      else:
        return game.play(self, self.c[self.cn-1])

